    void persist(Ink.Doc doc){Ink.Doc snapshot=doc.copy();store.enqueueWrite(snapshot,e->{if(e!=null)runOnUiThread(()->error("Не удалось сохранить документ",e));});}
    void saveNow(){ui.removeCallbacks(saveLater);if(current==null)return;canvas.finishGesture(false);canvas.stashViewport();Ink.Doc target=current,snapshot=current.copy();long version=revision;if(status!=null)status.setText("Сохранение…");store.enqueueWrite(snapshot,e->{if(e!=null){runOnUiThread(()->error("Не удалось сохранить. Экспортируйте копию",e));return;}runOnUiThread(()->{if(current==target&&revision==version){savedRevision=version;ui.removeCallbacks(backupLater);ui.postDelayed(backupLater,30000);if(status!=null)status.setText("Все изменения сохранены");}});});}
