    void writePenPrefs(){if(canvas==null)return;String persistedTool=canvas.invertedReturnTool==null?canvas.tool:canvas.invertedReturnTool;SharedPreferences.Editor edit=prefs.edit().putInt("tape_texture",canvas.tapeTexture).putString("tool",persistedTool).putInt("ink",canvas.color).putFloat("width",canvas.invertedReturnTool==null?canvas.width:canvas.widths.getOrDefault(persistedTool,canvas.width)).putFloat("eraser",canvas.eraserWidth).putFloat("compass_radius",canvas.compassRadius).putFloat("ruler_angle",canvas.ruler.degrees).putString("active_guide",canvas.guideMode).putBoolean("ruler_placed",canvas.ruler.placed).putFloat("ruler_screen_x",canvas.ruler.x).putFloat("ruler_screen_y",canvas.ruler.y).putBoolean("laser_trail",canvas.laser.trail).putBoolean("laser_pulse",canvas.laser.pulse).putInt("laser_color",canvas.laser.color);if(GuideTools.ink(canvas.tool))edit.putString("last_ink_tool",canvas.tool);canvas.rememberColor();for(Map.Entry<String,Integer> selected:canvas.presets.selection.entrySet())edit.putInt("preset_selected_"+selected.getKey(),selected.getValue());for(Map.Entry<String,int[]> preset:canvas.presets.colors.entrySet())for(int slot=0;slot<3;slot++)edit.putInt("preset_"+preset.getKey()+"_"+slot,preset.getValue()[slot]);for(Map.Entry<String,Integer> c:canvas.toolColors.saved.entrySet())edit.putInt("ink_"+c.getKey(),c.getValue());for(Map.Entry<String,Float> w:canvas.widths.entrySet())edit.putFloat("width_"+w.getKey(),w.getValue());if(!canvas.tool.equals("eraser"))edit.putFloat("width_"+canvas.tool,canvas.width);edit.apply();}
    void applyPenPrefs(){
        canvas.tapeTexture=Math.max(0,Math.min(5,prefs.getInt("tape_texture",0)));canvas.compassRadius=Ink.clamp(prefs.getFloat("compass_radius",180),5,2400);canvas.ruler.degrees=RulerGeometry.angle(prefs.getFloat("ruler_angle",0));canvas.ruler.placed=prefs.getBoolean("ruler_placed",false);canvas.ruler.x=prefs.getFloat("ruler_screen_x",0);canvas.ruler.y=prefs.getFloat("ruler_screen_y",0);canvas.autoShapes=prefs.getBoolean("auto_shapes",true);canvas.laser.trail=prefs.getBoolean("laser_trail",false);canvas.laser.pulse=prefs.getBoolean("laser_pulse",true);canvas.laser.color=prefs.getInt("laser_color",LaserEffect.DEFAULT_COLOR);canvas.pressure=prefs.getBoolean("pressure",true);canvas.showHover=prefs.getBoolean("hover",true);canvas.fingerDraw=prefs.getBoolean("finger",false);canvas.edgeSwipe=prefs.getBoolean("edge",true);canvas.rotationEnabled=prefs.getBoolean("rotation",true);canvas.eraserMode=prefs.getString("eraserMode","area");canvas.tool=prefs.getString("tool","pen");canvas.guideMode=prefs.getString("active_guide",GuideTools.mode(canvas.tool));if(!Arrays.asList("none","ruler","compass").contains(canvas.guideMode))canvas.guideMode="none";if(GuideTools.auxiliary(canvas.tool))canvas.tool=prefs.getString("last_ink_tool","pen");if(!Arrays.asList(Ink.TOOLS).contains(canvas.tool)||GuideTools.auxiliary(canvas.tool))canvas.tool="pen";canvas.previous=canvas.tool.equals("eraser")?"pen":canvas.tool;int legacy=prefs.getInt("ink",0xff28344b);for(String name:Ink.TOOLS)if(ToolColors.enabled(name))canvas.toolColors.put(name,prefs.getInt("ink_"+name,name.equals("laser")?canvas.laser.color:prefs.contains("ink")?legacy:ColorDefaults.first(name)));canvas.color=canvas.toolColors.get(canvas.tool,legacy);canvas.laser.color=canvas.toolColors.get("laser",canvas.laser.color);
        for(String name:Ink.TOOLS)if(ToolColors.enabled(name)){int[] defaults=ColorDefaults.forTool(name);for(int slot=0;slot<3;slot++)canvas.presets.put(name,slot,prefs.getInt("preset_"+name+"_"+slot,slot==0?canvas.colorFor(name):defaults[slot]));canvas.presets.select(name,prefs.getInt("preset_selected_"+name,0));}
        for(String name:Ink.TOOLS)canvas.widths.put(name,prefs.getFloat("width_"+name,Ink.defaultWidth(name)));canvas.width=canvas.widths.get(canvas.tool);if(canvas.tool.equals("laser"))canvas.width=Ink.clamp(canvas.width,2,18);canvas.eraserWidth=prefs.getFloat("eraser",42);if(Float.isFinite(PenProvider.rotationDegrees)&&SystemClock.uptimeMillis()-PenProvider.rotationAt<1500)canvas.rotation(PenProvider.rotationDegrees,PenProvider.rotationAt);
    }
