    void sideNav(LinearLayout side,String glyph,String label,String target,boolean selected){LinearLayout r=row();pad(r,12,8);r.setBackground(bg(selected?0xff233c56:Color.TRANSPARENT,13));Icons i=new Icons(this,glyph);i.tint=selected?ACCENT:MUTED;r.addView(i,new LinearLayout.LayoutParams(dp(26),dp(32)));space(r,12);TextView title=text(label,14,selected?ACCENT:0xff69748a,selected);title.setSingleLine();title.setEllipsize(TextUtils.TruncateAt.END);r.addView(title,new LinearLayout.LayoutParams(0,-2,1));r.setOnClickListener(v->{folder=target;library();});if(!target.isEmpty())r.setOnLongClickListener(v->{folderMenu(target);return true;});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);side.addView(r,lp);}
    void fillGrid(LinearLayout grid){grid.removeAllViews();ArrayList<Ink.Doc> visible=new ArrayList<>();for(Ink.Doc d:docs)if((folder.isEmpty()||folder.equals(d.folder))&&d.title.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))visible.add(d);visible.sort((a,b)->Long.compare(b.modified,a.modified));int cols=wide()?Math.max(2,(getResources().getConfiguration().screenWidthDp-290)/210):2;
        for(int start=0;start<visible.size();start+=cols){LinearLayout r=row();r.setGravity(Gravity.TOP);for(int j=0;j<cols;j++){if(j>0)space(r,18);if(start+j<visible.size()){Ink.Doc d=visible.get(start+j);LinearLayout card=column();Cover cover=new Cover(d);cover.setContentDescription("Открыть "+d.title);cover.setOnClickListener(v->open(d));cover.setOnLongClickListener(v->{docMenu(d);return true;});card.addView(cover,new LinearLayout.LayoutParams(-1,dp(wide()?206:186)));LinearLayout title=row();TextView name=text(d.title,14,INK,true);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);title.addView(name,new LinearLayout.LayoutParams(0,-2,1));addIcon(title,"more","Действия с тетрадью",()->docMenu(d));card.addView(title);TextView date=text(d.pages.size()+" стр.  ·  "+new SimpleDateFormat("d MMM",new Locale("ru")).format(new Date(d.modified)),11,MUTED,false);card.addView(date);r.addView(card,new LinearLayout.LayoutParams(0,-2,1));}else r.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(24);grid.addView(r,lp);}
        if(visible.isEmpty()){TextView empty=text(query.isEmpty()?"Здесь пока чистый лист\nСоздайте тетрадь или импортируйте PDF":"Ничего не найдено",17,MUTED,false);empty.setGravity(Gravity.CENTER);pad(empty,8,70);grid.addView(empty);}
    }
    final class Cover extends View {Ink.Doc d;Cover(Ink.Doc d){super(MainActivity.this);this.d=d;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        protected void onDraw(Canvas c){Paint p=new Paint(3);float w=getWidth(),h=getHeight();p.setColor(d.cover);c.drawRoundRect(new RectF(0,0,w,h),dp(15),dp(15),p);p.setColor(0x15000000);c.drawRoundRect(new RectF(dp(12),0,dp(15),h),dp(1),dp(1),p);p.setColor(0x18ffffff);c.drawCircle(w,h*.9f,w*.75f,p);p.setColor(0x30ffffff);c.drawCircle(w*.9f,-h*.1f,w*.65f,p);p.setColor(0xff425274);p.setTextSize(dp(10));p.setTypeface(Typeface.create("sans-serif-medium",0));c.drawText("F O L I O",dp(30),dp(34),p);p.setTextSize(dp(18));float y=h*.53f;String title=d.title;while(p.measureText(title)>w-dp(55)&&title.length()>1)title=title.substring(0,title.length()-1);if(!title.equals(d.title))title+="…";c.drawText(title,dp(28),y,p);p.setColor(0x55617193);p.setStrokeWidth(dp(1));c.drawLine(dp(28),y+dp(18),Math.min(w-dp(28),dp(95)),y+dp(18),p);p.setTextSize(dp(9));p.setColor(0xff7380a0);c.drawText("ЗАМЕТКИ И МЫСЛИ",dp(28),h-dp(26),p);}}
    void open(Ink.Doc doc){flushToolUpdates();if(current!=null&&current!=doc){audio.pause();saveNow();backup.automatic(current.copy());}current=doc;prefs.edit().putString("last",doc.id).apply();revision=savedRevision=0;focusMode=false;showPages=wide();buildEditor();}
    void buildEditor(){StudioWorkspace.editor(this);}
    void refreshTools(){StudioWorkspace.refresh(this);}
    void rebuildPageStrip(){if(current==null||body==null)return;LinearLayout work=(LinearLayout)body.getParent(),holder=(LinearLayout)work.getChildAt(1);holder.removeAllViews();holder.setVisibility(showPages?View.VISIBLE:View.GONE);if(!showPages)return;holder.setBackgroundColor(0xff1e2228);ScrollView scroll=new ScrollView(this);thumbs=column();pad(thumbs,12,14);for(int i=0;i<current.pages.size();i++){final int index=i;LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setBackground(bg(i==current.current?0xff233c56:Color.TRANSPARENT,11));pad(item,7,8);View thumb=new PageThumb(current.pages.get(i));thumb.setContentDescription("Страница "+(i+1));item.addView(thumb,new LinearLayout.LayoutParams(dp(79),dp(105)));TextView number=text((current.pages.get(i).bookmark.isEmpty()?"":"◆ ")+(i+1),10,i==current.current?ACCENT:MUTED,false);number.setGravity(Gravity.CENTER);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(7);item.addView(number,np);item.setOnClickListener(v->goPage(index));item.setOnLongClickListener(v->{pageMenu(index);return true;});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);thumbs.addView(item,lp);}scroll.addView(thumbs);holder.addView(scroll,new LinearLayout.LayoutParams(dp(118),0,1));TextView add=pill("+",false,this::addPage);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(43));lp.setMargins(dp(12),0,dp(12),dp(12));holder.addView(add,lp);}
    final class PageThumb extends View {Ink.Page p;PageThumb(Ink.Page p){super(MainActivity.this);this.p=p;}protected void onDraw(Canvas c){c.save();if(p.infinite){float[] bounds=CanvasViewport.exportBounds(p);float scale=Math.min(getWidth()/(bounds[2]-bounds[0]),getHeight()/(bounds[3]-bounds[1]));c.drawColor(p.paper);c.translate((getWidth()-(bounds[2]-bounds[0])*scale)/2,(getHeight()-(bounds[3]-bounds[1])*scale)/2);c.scale(scale,scale);c.translate(-bounds[0],-bounds[1]);InkRenderer.region(c,p,null,p.strokes,Collections.emptySet(),bounds[0],bounds[1],bounds[2],bounds[3],scale);}else {c.scale(getWidth()/p.width,getHeight()/p.height);c.clipRect(0,0,p.width,p.height);InkRenderer.page(c,p,null,Collections.emptySet());}if(!p.background.isEmpty()){Paint label=new Paint(3);label.setColor(0xff8b96ab);label.setTextSize(110);c.drawText("PDF / IMG",100,180,label);}c.restore();}}
    void goPage(int index){if(current==null||index<0||index>=current.pages.size()||index==current.current)return;canvas.finishGesture(false);current.current=index;canvas.open(current);pageCount.setText(pageCaption());rebuildPageStrip();changed();}
    @Override public void page(int direction){if(current==null)return;int i=current.current+direction;if(i<0||i>=current.pages.size()){toast(i<0?"Это первая страница":"Последняя страница. Нажмите +, чтобы добавить");return;}goPage(i);}
    void addPage(){canvas.finishGesture(false);Ink.Page old=current.page(),p=new Ink.Page();p.paper=old.paper;p.lines=old.lines;p.spacing=old.spacing;p.pattern=old.pattern;p.width=old.width;p.height=old.height;p.infinite=old.infinite;current.pages.add(current.current+1,p);int target=current.current+1;goPage(target);changed();}
    void pageMenu(int index){String[] options={"Открыть","Дублировать","Переместить влево","Переместить вправо","Удалить страницу",current.pages.get(index).bookmark.isEmpty()?"Добавить закладку":"Удалить закладку"};new Studio.Builder(this).setTitle("Страница "+(index+1)).setItems(options,(d,w)->{canvas.finishGesture(false);if(w==0)goPage(index);if(w==1){Ink.Page p=current.pages.get(index).copy();p.id=Ink.id();current.pages.add(index+1,p);goPage(index+1);changed();}if(w==2&&index>0){Collections.swap(current.pages,index,index-1);current.current=index-1;canvas.open(current);changed();}if(w==3&&index<current.pages.size()-1){Collections.swap(current.pages,index,index+1);current.current=index+1;canvas.open(current);changed();}if(w==5){if(index!=current.current)goPage(index);if(current.page().bookmark.isEmpty())NotebookNavigator.bookmark(this);else NotebookNavigator.remove(this);}if(w==4){if(current.pages.size()==1){toast("В тетради должна остаться хотя бы одна страница");return;}confirm("Удалить страницу?","Штрихи на этой странице будут удалены.",()->{current.pages.remove(index);current.current=Math.min(current.current,current.pages.size()-1);canvas.open(current);changed();rebuildPageStrip();pageCount.setText(pageCaption());});}rebuildPageStrip();}).show();}
    void editorMenu(){FeatureStudio.show(this);}
    void toggleFocus(){focusMode=!focusMode;editorHeader.setVisibility(focusMode?View.GONE:View.VISIBLE);for(View view:chrome)view.setVisibility(focusMode?View.GONE:View.VISIBLE);systemBars(false);}
    void systemBars(boolean show){systemBarsVisible=show;SystemChrome.apply(getWindow(),show);if(root!=null)root.requestApplyInsets();}
    Ink.Doc blankNotebook(String name){Ink.Doc d=new Ink.Doc();d.pages.set(0,CanvasDefaults.read(prefs));d.title=uniqueTitle(name,null);d.folder=folder;d.cover=COVERS[docs.size()%COVERS.length];return d;}
