    String bridgeText(){if(nativePenOnly())return "Проверка без ADB · "+(penSdk==null?"SDK ожидает запуска":penSdk.summary());if(!StylusDevices.bridge())return "Стандартное перо Android · мост не требуется\n"+(canvas==null?"Откройте холст для проверки пера":canvas.input.summary());return (PenProvider.connected()?"● Мост подключён":"○ Мост не подключён")+"\nРежим: "+PenProvider.state+"\nУстройство: "+(PenProvider.device.isEmpty()?"ожидание пера":PenProvider.device)+"\nПоследний сигнал: "+PenProvider.lastEvent+"\n"+(haptics==null?"":"Отклик пера: "+haptics.state+"\n")+(rotation==null?"":rotation.state)+"\nВращение: "+(Float.isFinite(PenProvider.rotationDegrees)?String.format(Locale.ROOT,"%.0f° · %d сигналов",PenProvider.rotationDegrees,PenProvider.rotationEvents):"нет сигнала от датчика");}
