    void keySettings(){if(penSettingsDialog!=null){penSettingsDialog.dismiss();penSettingsDialog=null;}ScrollView scroll=new ScrollView(this);LinearLayout box=column();pad(box,24,10);scroll.addView(box);TextView note=text("Коды Linux EV_KEY. На этом Focus Pen Pro получены: 96 — распознанный двойной тап, 189 — сжатие, 73/81 — свайпы. Одиночный тап эта прошивка не передаёт. Для другого пера можно обучить отдельный сигнал одиночного тапа. Ноль отключает жест.",13,MUTED,false);box.addView(note);String[] labels={"Одиночный тап (0 — нет сигнала)","Сжатие","Предыдущая страница","Следующая страница","Двойной тап"},keys={"tapCode","squeezeCode","prevCode","nextCode","doubleCode"};int[] defaults={0,189,73,81,96};EditText[] inputs=new EditText[5];for(int i=0;i<inputs.length;i++){TextView label=text(labels[i],13,INK,true);pad(label,0,14);box.addView(label);EditText edit=Studio.input(this,"","");edit.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);edit.setText(""+prefs.getInt(keys[i],defaults[i]));inputs[i]=edit;box.addView(edit);}Studio.Sheet d=new Studio.Builder(this).setTitle("Сигналы пера").setView(scroll).setNegativeButton("Отмена",null).setNeutralButton("Обучить жест",(dialog,which)->{new Studio.Builder(this).setTitle("Какой жест обучить?").setItems(labels,(pick,index)->{ui.postDelayed(()->learn(keys[index],labels[index]),200);}).show();}).setPositiveButton("Сохранить",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(x->{HashSet<Integer> seen=new HashSet<>();SharedPreferences.Editor e=prefs.edit();for(int i=0;i<inputs.length;i++){try{int n=Integer.parseInt(inputs[i].getText().toString());if(n<0||n>767||(n!=0&&!seen.add(n)))throw new IllegalArgumentException();e.putInt(keys[i],n);}catch(Exception ex){inputs[i].setError("Укажите уникальный код от 1 до 767");return;}}e.apply();d.dismiss();}));d.show();}
    public boolean penPriority(){return resumed&&!isFinishing()&&!isDestroyed();}
