    public boolean penActive(){return resumed&&focused&&current!=null&&canvas!=null&&intro==null&&launch==null&&eyedropper==null&&!setupOpen;}
    public boolean suppress(){return !nativePenOnly()&&prefs.getBoolean("suppress",true);}
    public void hardware(long timestamp,int code,int value){
        if(!penActive()||nativePenOnly())return;
        timestamp=EventTiming.uptime(timestamp,SystemClock.uptimeMillis(),System.currentTimeMillis());
        if(learningKey!=null&&value==1){String key=learningKey;SharedPreferences.Editor edit=prefs.edit();for(String other:new String[]{"tapCode","doubleCode","squeezeCode","prevCode","nextCode"})if(!other.equals(key)&&prefs.getInt(other,0)==code)edit.putInt(other,0);edit.putInt(key,code).apply();closeLearning();toast("Запомнен сигнал Linux "+code);return;}
        if(code==squeezeCode()&&code!=0){actions.squeeze(timestamp,value);return;}
        if(value!=1)return;
        if(code==tapCode()&&code!=0){taps.tap(timestamp,this);ui.removeCallbacks(tapTimeout);if(taps.deadline()>=0)ui.postDelayed(tapTimeout,Math.max(0,taps.deadline()-SystemClock.uptimeMillis()));}
        else if(code==prefs.getInt("doubleCode",96)){taps.cancel();doubleTap();}
        else if(code==prefs.getInt("prevCode",73))actions.run("up");
        else if(code==prefs.getInt("nextCode",81))actions.run("down");
    }
    void learn(String key,String gesture){if(current==null){toast("Сначала откройте тетрадь");return;}learningKey=key;taps.cancel();canvas.closePalette();learningOverlay=new FrameLayout(this);learningOverlay.setBackgroundColor(0x990f1730);learningOverlay.setClickable(true);LinearLayout card=column();pad(card,28,24);card.setBackground(bg(BG,24));TextView title=text("Обучение жеста",24,INK,true);card.addView(title);TextView prompt=text("Сделайте: "+gesture+"\n\nОжидаю отдельный сигнал от пера. Не касайтесь экрана наконечником. Если сигнал не поступает, прошивка может не передавать этот жест приложению.",16,MUTED,false);prompt.setLineSpacing(dp(4),1);pad(prompt,0,20);card.addView(prompt);card.addView(pill("Отмена",false,this::closeLearning));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(400),-2,Gravity.CENTER);learningOverlay.addView(card,lp);root.addView(learningOverlay,new FrameLayout.LayoutParams(-1,-1));}
    void closeLearning(){learningKey=null;if(learningOverlay!=null){root.removeView(learningOverlay);learningOverlay=null;}}
    @Override public void single(){if(penActive())actions.run("single");}
    @Override public void doubleTap(){if(penActive()){if(haptics!=null)haptics.doubleTap();actions.run("double");}}
    void stylusButton(int button,int device,long time,int source){if(penActive()&&stylusButtons.accept(button,device,time,source))gesture(button==0?"button_primary":"button_secondary");}
    @Override public boolean dispatchKeyEvent(KeyEvent event){
        if(penActive()&&nativePenOnly()&&penSdk!=null&&penSdk.key(event))return true;
        if(penActive()&&(event.getKeyCode()==KeyEvent.KEYCODE_STYLUS_BUTTON_PRIMARY||event.getKeyCode()==KeyEvent.KEYCODE_STYLUS_BUTTON_SECONDARY)){
            if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0&&!event.isCanceled())stylusButton(event.getKeyCode()==KeyEvent.KEYCODE_STYLUS_BUTTON_PRIMARY?0:1,event.getDeviceId(),event.getEventTime(),StylusButtons.KEY);return true;}

        if(penActive()&&event.getScanCode()!=0&&StylusDevices.scanCode(event.getDevice())){int code=event.getScanCode();if(code==tapCode()||code==prefs.getInt("doubleCode",96)||code==squeezeCode()||code==prefs.getInt("prevCode",73)||code==prefs.getInt("nextCode",81)){if(event.getRepeatCount()==0&&!PenProvider.connected())hardware(event.getEventTime(),code,event.getAction()==KeyEvent.ACTION_DOWN?1:0);return true;}}
        if(penActive()&&event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0){if(event.isCtrlPressed()&&event.getKeyCode()==KeyEvent.KEYCODE_Z){if(event.isShiftPressed())canvas.redo();else canvas.undo();return true;}if(event.isCtrlPressed()&&event.getKeyCode()==KeyEvent.KEYCODE_Y){canvas.redo();return true;}}
        return super.dispatchKeyEvent(event);
    }
    void importPicker(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/*","application/zip","application/octet-stream"});startActivityForResult(intent,10);}
    void exportDialog(){if(current==null)return;canvas.finishGesture(false);new Studio.Builder(this).setTitle("Экспортировать").setItems(new String[]{"Folio · редактируемая тетрадь со всеми страницами","PDF · все страницы","PNG · текущая страница"},(d,w)->{exportKind=new String[]{"folio","pdf","png"}[w];exportSnapshot=current.copy();exportPage=current.current;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(w==0?"application/octet-stream":w==1?"application/pdf":"image/png");i.putExtra(Intent.EXTRA_TITLE,current.title.replaceAll("[\\\\/:*?\"<>|]","_")+"."+exportKind);startActivityForResult(i,11);}).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==BackupStudio.PICK){backup.selected(data);return;}if(request==10){String name="Импорт";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}String mime=getContentResolver().getType(uri),fileName=name;Studio.Sheet progress=Studio.busy(this,"Импорт","Подготовка страниц…");store.io.execute(()->{try{Ink.Doc imported=store.importFile(uri,mime,fileName);imported.folder=folder;store.write(imported);runOnUiThread(()->{progress.dismiss();if(isDestroyed())return;imported.title=uniqueTitle(imported.title,imported);docs.add(0,imported);persist(imported);open(imported);toast("Документ импортирован");});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->{progress.dismiss();error("Не удалось импортировать файл",e);});}});}else if(request==11&&exportSnapshot!=null){Ink.Doc d=exportSnapshot;String kind=exportKind;int page=exportPage;exportSnapshot=null;Studio.Sheet progress=Studio.busy(this,"Экспорт","Запись файла…");store.io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Файл недоступен");if(kind.equals("folio"))store.exportArchive(d,out);else if(kind.equals("pdf"))store.exportPdf(d,out);else store.exportPng(d.pages.get(page),out);runOnUiThread(()->{progress.dismiss();toast("Файл экспортирован");});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->{progress.dismiss();error("Экспорт не завершён",e);});}});}}
    void help(){new Studio.Builder(this).setTitle("Folio · инструменты").setMessage("Перо рисует. Пальцы перемещают и масштабируют лист, короткое касание двумя пальцами отменяет действие.\n\nВ настройках можно назначить действия двойному тапу, сжатию, удержанию, двойному сжатию, свайпам и кнопкам пера. Одиночный тап корпуса Focus Pen Pro эта прошивка отдельно не передаёт.\n\nНарисуйте фигуру и задержите перо в конце: Folio выровняет линию, окружность, овал, квадрат, прямоугольник, треугольник, трапецию, параллелограмм, ромб, многоугольник, облако, сердце или звезду. Продолжите движение, чтобы вернуться к исходному штриху.\n\nУдержание инструмента открывает его настройки. Кнопка + в пенале меняет набор и порядок инструментов. Лента скрывает содержимое: выберите навигацию и коснитесь ленты, чтобы показать её. Лазер исчезает и не сохраняется.\n\nЛастик «В пределах окружности» стирает только внутри круга; при наведении скрывается тот же участок. В режиме «Целый штрих» временно скрывается всё действие. Круг виден и во время стирания.\n\nВкладка «Чертёж»: линейка и циркуль включаются отдельно от пера. Бесконечная линейка остаётся на экране: двигайте одним пальцем, поворачивайте двумя. У циркуля выберите центр, задайте радиус в настройках и вручную проведите нужную дугу. Транспортир поворачивается движением пера от центра.\n\nВращение кисти получает угол от системной службы PencilEngine. Помощник жестов проверяется и запускается при открытии Folio или FocusFlow. Если беспроводная отладка выключена, появится кнопка настроек. Первое сопряжение по коду Android выполняется один раз в FocusFlow.\n\nPDF импортируется фоном, Folio сохраняет редактируемые штрихи и маски ластика. Автосохранение работает после действий и при выходе.").setPositiveButton("Понятно",null).show();}
    Ink.Doc welcome(){Ink.Doc d=new Ink.Doc();d.title="Начните с идеи";Ink.Page p=d.page();p.pattern="dots";p.lines=0xffe1e5ef;addWelcomeText(p,"Место для ваших мыслей",100,150,51,0xff28344b);addWelcomeText(p,"Пишите. Рисуйте. Оставляйте важное.",100,240,24,0xff8793aa);Ink.Stroke line=new Ink.Stroke();line.color=0xff8896e6;line.width=8;for(int x=105;x<930;x+=5)line.points.add(new Ink.Pt(x,335+(float)Math.sin(x*.012)*10,.8f,0,0));p.strokes.add(line);addWelcomeText(p,"ПЕРО И ЛИСТ",100,430,19,ACCENT);addWelcomeText(p,"01   Перо рисует, пальцы перемещают лист.\n02   Два пальца — отмена последнего действия.\n03   Свайп от края — следующая страница.\n04   Настройте бумагу и цвет под настроение.",100,495,27,0xff53637b);addWelcomeText(p,"Нажим меняет линию",100,800,31,0xff28344b);for(int j=0;j<3;j++){Ink.Stroke s=new Ink.Stroke();s.tool=j==0?"pen":j==1?"brush":"marker";s.color=new int[]{0xff6979de,0xff68a497,0xffe8b94d}[j];s.width=j==0?9:26;for(int i=0;i<150;i++)s.points.add(new Ink.Pt(105+i*5,930+j*100+(float)Math.sin(i*.07f)*22,.15f+i/180f,.3f,-.4f));p.strokes.add(s);}addWelcomeText(p,"Это настоящая тетрадь. Попробуйте инструменты\nили создайте свою в библиотеке.",100,1330,25,0xff8793aa);return d;}
    void addWelcomeText(Ink.Page p,String value,float x,float y,float width,int color){Ink.Stroke s=new Ink.Stroke();s.tool="text";s.text=value;s.width=width;s.color=color;s.points.add(new Ink.Pt(x,y,1,0,0));p.strokes.add(s);}
    @Override public boolean dispatchGenericMotionEvent(MotionEvent event){if(nativePenOnly()&&penSdk!=null&&penSdk.motion(event))return true;if(!nativePenOnly()&&rotation!=null&&rotation.event(event))return true;return super.dispatchGenericMotionEvent(event);}
    void toolbarDialog(){ToolStudio.panel(this);}
    @Override public void gesture(String name){if(actions!=null)actions.run(name);}
    void toast(String message){if(!isDestroyed())Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
    void error(String title,Throwable e){android.util.Log.e("Folio",title,e);if(!isDestroyed())new Studio.Builder(this).setTitle(title).setMessage(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()).setPositiveButton("Понятно",null).show();}
    @Override protected void onResume(){super.onResume();resumed=true;if(agent!=null)agent.resume();
        if(penSdk==null)penSdk=new ru.folio.penbridge.XiaomiPenSdk(this,true,new ru.folio.penbridge.XiaomiPenSdk.Sink(){
            public void gesture(int key,boolean down,long time){if(!penActive())return;if(key==194)actions.squeeze(time,down?1:0);else if(down){if(key==195)doubleTap();else actions.run(key==196?"up":"down");}}
            public void rotation(int degree,long time){if(!penActive()||!canvas.rotationEnabled)return;PenProvider.rotationSource="Xiaomi official SDK";PenProvider.rotationDegrees=degree;PenProvider.rotationAt=SystemClock.uptimeMillis();PenProvider.rotationEvents++;canvas.rotation(degree,time);}
        });if(nativePenOnly())penSdk.resume();else penSdk.pause();PenProvider.activity=new java.lang.ref.WeakReference<>(this);priorityChanged();systemBars(false);if(StylusDevices.bridge()&&!nativePenOnly()){if(autoAdb==null)autoAdb=new ru.folio.penbridge.AutoAdbClient(this);autoAdb.resume();}else if(autoAdb!=null)autoAdb.pause();ui.removeCallbacks(tick);ui.post(tick);}
    @Override protected void onPause(){if(handwritingSetup!=null)handwritingSetup.persistDraft();if(agent!=null)agent.pause();if(penSdk!=null)penSdk.pause();if(autoAdb!=null)autoAdb.pause();flushToolUpdates();if(eyedropper!=null)eyedropper.close();resumed=false;priorityChanged();if(audio!=null)audio.pause();ui.removeCallbacks(backupLater);if(nativePenOnly()&&penSdk!=null)penSdk.update();if(rotation!=null&&!nativePenOnly())rotation.update();if(haptics!=null)haptics.update();taps.cancel();ui.removeCallbacks(tapTimeout);actions.cancel();closeLearning();if(canvas!=null){canvas.finishGesture(false);canvas.clearLaser();canvas.closePalette();canvas.hoverHidden.clear();canvas.hoverX=-1;saveNow();if(backup!=null)backup.automatic(current.copy());}ui.removeCallbacks(tick);systemBars(true);super.onPause();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);focused=focus;if(nativePenOnly()&&penSdk!=null)penSdk.update();if(rotation!=null&&!nativePenOnly())rotation.update();if(haptics!=null)haptics.update();if(focus&&canvas!=null)systemBars(false);if(!focus){taps.cancel();ui.removeCallbacks(tapTimeout);actions.cancel();if(canvas!=null){canvas.finishGesture(false);canvas.clearLaser();canvas.hoverHidden.clear();canvas.hoverX=-1;canvas.invalidate();}}}
    @Override public void onConfigurationChanged(Configuration c){int slide=intro==null?-1:intro.index;HandwritingSetup prior=handwritingSetup;int setupPage=prior==null?0:prior.page,setupGroup=prior==null?0:prior.group,setupIndex=prior==null?0:prior.index;JSONArray strokes=prior==null||prior.pad==null||!prior.pad.isEnabled()?null:prior.pad.json();super.onConfigurationChanged(c);if(ready){if(current==null)library();else buildEditor();if(slide>=0){Onboarding.show(this,true);intro.index=slide;intro.fill();}else if(prior!=null){HandwritingSetup.show(this,false);if(handwritingSetup!=null)handwritingSetup.restoreAfterLayout(setupPage,setupGroup,setupIndex,strokes);}}}
    @Override public void onBackPressed(){if(eyedropper!=null){eyedropper.close();return;}if(handwritingSetup!=null){handwritingSetup.back();return;}if(intro!=null){if(intro.index>0)intro.go(intro.index-1);else intro.finish(true);}else if(learningKey!=null)closeLearning();else if(canvas!=null&&(canvas.radial||canvas.radialClosing)){canvas.hidePalette();}else if(current!=null)library();else super.onBackPressed();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==AudioStudio.PERMISSION&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&audio!=null)audio.start();}
    @Override protected void onDestroy(){if(handwritingSetup!=null){handwritingSetup.persistDraft();handwritingSetup.closeNow();}if(autoAdb!=null)autoAdb.close();flushToolUpdates();if(audio!=null)audio.pause();if(ocr!=null)ocr.worker.shutdown();if(backup!=null)backup.worker.shutdown();if(launch!=null)launch.closeNow(false);resumed=false;focused=false;if(haptics!=null)haptics.close();if(rotation!=null)rotation.close();ui.removeCallbacksAndMessages(null);if(PenProvider.activity.get()==this)PenProvider.activity.clear();store.io.shutdown();super.onDestroy();}
